def maximum_station_assignment_gap(skill,station):
    n=len(skill);latest=[0]*n;j=len(station)-1
    for i in range(n-1,-1,-1):
        while station[j]!=skill[i]:j-=1
        latest[i]=j;j-=1
    answer=0;j=0
    for i in range(n-1):
        while station[j]!=skill[i]:j+=1
        answer=max(answer,latest[i+1]-j);j+=1
    return answer

